package com.beatoflove.standardcalculator;
import android.app.*;import android.content.*;import android.widget.*;import org.json.*;import java.math.*;import java.util.*;
final class CurrencyPanel extends PanelUi {
 static final String[] CURRENCIES={"USD","THB","EUR","JPY","GBP","CNY","SGD","AUD","CHF","HKD","MYR","CAD","NZD","KRW","INR","IDR","PHP","VND","TWD","AED","SAR","SEK","NOK","DKK"};
 static final String[] BANKS={"Bangkok Bank","Kasikornbank","SCB","Krungthai Bank","Krungsri","ttb"};
 static final String[] BANK_URL={"https://www.bangkokbank.com/th/personal/other-services/view-rates/foreign-exchange-rates","https://www.kasikornbank.com/","https://www.scb.co.th/","https://krungthai.com/","https://www.krungsri.com/","https://www.ttbbank.com/"};
 final SharedPreferences prefs; int generation; boolean active; Runnable resumeFetch; final android.os.Handler timer=new android.os.Handler(android.os.Looper.getMainLooper()); Runnable bankPoll;
 CurrencyPanel(Activity a){super(a);prefs=a.getSharedPreferences("currency53",0);}
 void stop(){active=false;generation++;if(bankPoll!=null)timer.removeCallbacks(bankPoll);} void resume(){active=true;if(resumeFetch!=null)resumeFetch.run();} void attach(LinearLayout p){active=true;resumeFetch=null;LinearLayout l=screen(p,"Currency","Convert · Bank Rates · Compare");Spinner m=spin(l,"Mode",new String[]{"Convert","Bank Rates","Compare"});LinearLayout b=col();l.addView(b);selected(m,()->{generation++;if(bankPoll!=null)timer.removeCallbacks(bankPoll);resumeFetch=null;b.removeAllViews();if(m.getSelectedItemPosition()==0)convert(b);else bank(b,m.getSelectedItemPosition()==2);});}
 String s(Spinner sp){return String.valueOf(sp.getSelectedItem());}
 void convert(LinearLayout l){Spinner source=spin(l,"Rate source",new String[]{"Daily reference (Frankfurter)","Latest Forex quote (cached)"});Spinner from=spin(l,"From",CURRENCIES),to=spin(l,"To",CURRENCIES);to.setSelection(1);EditText amount=input(l,"Amount","1",false);TextView out=result(l),status=text("",12,MUTE,false);l.addView(status);final BigDecimal[] rate={null};final String[] pair={""};final int[] seq={0};Runnable calc=()->{try{if(rate[0]==null||!pair[0].equals(s(from)+"/"+s(to))){out.setText("—");return;}out.setText(FinancialMath.dec(amount.getText().toString()).multiply(rate[0],FinancialMath.MC).setScale(4,RoundingMode.HALF_UP).stripTrailingZeros().toPlainString()+" "+s(to));}catch(Exception e){out.setText("—");}};Runnable fetch=()->{if(!active)return;final String src=s(from),dst=s(to),key=src+"/"+dst;final int g=generation, id=++seq[0];pair[0]=key;rate[0]=null;if(src.equals(dst)){rate[0]=BigDecimal.ONE;status.setText("Same currency");calc.run();return;}if(source.getSelectedItemPosition()==1){try{SharedPreferences quotes=a.getSharedPreferences("live_markets53",0);String raw=quotes.getString("q:"+key,"");boolean inverse=raw.isEmpty();if(inverse)raw=quotes.getString("q:"+dst+"/"+src,"");JSONObject q=new JSONObject(raw);BigDecimal r=new BigDecimal(q.getString("p"));long stamp=q.getLong("t");if(r.signum()<=0||stamp<=0)throw new Exception();rate[0]=inverse?BigDecimal.ONE.divide(r,MathContext.DECIMAL128):r;status.setText("Cached "+q.optString("source","Twelve Data")+" quote · "+new Date(stamp)+" · not live / not bank rate");}catch(Exception e){status.setText("No cached Forex quote for this pair. Open Markets → Forex first.");}calc.run();return;}String cache=prefs.getString("ref:"+key,"");try{JSONObject j=new JSONObject(cache);rate[0]=new BigDecimal(j.getString("rate"));status.setText("Cached reference · "+j.getString("date"));}catch(Exception ex){status.setText("Fetching daily reference…");}calc.run();if(src.equals(dst)){rate[0]=BigDecimal.ONE;status.setText("Same currency");calc.run();return;}PriceService.reference(src,dst,(j,err)->{if(!active||g!=generation||id!=seq[0])return;if(j==null){status.setText((rate[0]==null?"Unavailable":"Cached reference")+" · "+err);return;}try{BigDecimal r=new BigDecimal(j.getString("rate"));String date=j.getString("date");if(r.signum()<=0||!src.equals(j.getString("base"))||!dst.equals(j.getString("quote")))throw new Exception();java.time.LocalDate parsed=java.time.LocalDate.parse(date);if(parsed.isAfter(java.time.LocalDate.now().plusDays(1)))throw new Exception();if(rate[0]!=null&&!cache.isEmpty()){try{String old=new JSONObject(cache).getString("date");if(parsed.isBefore(java.time.LocalDate.parse(old))){status.setText("Cached reference · newer than provider response · "+old);return;}}catch(org.json.JSONException ignored){}}rate[0]=r;prefs.edit().putString("ref:"+key,j.toString()).apply();status.setText("Frankfurter · daily reference · "+date+"\n1 "+src+" = "+r+" "+dst);calc.run();}catch(Exception ex){status.setText("Invalid response · not updated");}});};resumeFetch=fetch;selected(source,fetch);selected(from,fetch);selected(to,fetch);watch(amount,calc);action(l,"⇅ Swap currencies",()->{int i=from.getSelectedItemPosition();from.setSelection(to.getSelectedItemPosition());to.setSelection(i);});keys(l,new String[][]{{"7","8","9"},{"4","5","6"},{"1","2","3"},{".","0","⌫"}},k->{String x=amount.getText().toString();if(k.equals("⌫"))amount.setText(x.isEmpty()?x:x.substring(0,x.length()-1));else if(!k.equals(".")||!x.contains("."))amount.setText(x+k);});action(l,"Refresh selected rate",fetch);l.addView(text("Daily institutional reference, not a live trading or bank counter rate.",12,MUTE,false));}
 void bank(LinearLayout l,boolean compare){
  Spinner type=spin(l,"Rate type",new String[]{"Banknotes","Transfer (TT)"});
  Spinner currency=compare?spin(l,"Currency",Arrays.stream(CURRENCIES).filter(c->!c.equals("THB")).toArray(String[]::new)):null;
  Spinner direction=compare?spin(l,"Transaction",new String[]{"Bank Buys","Bank Sells"}):null;
  Spinner denomination=spin(l,"USD note denomination",new String[]{"50-100","5-20","1-2"});
  EditText amount=compare?input(l,"Amount (optional)","",false):null;
  Spinner chosen=compare?null:spin(l,"Bank",BANKS);if(chosen!=null)chosen.setSelection(1);
  LinearLayout rows=col();l.addView(rows);TextView status=text("Loading bank rate boards…",12,MUTE,false);l.addView(status);
  Map<Integer,JSONObject> boards=new HashMap<>();Map<Integer,String> states=new HashMap<>();final int[] request={0};
  Runnable render=()->{rows.removeAllViews();boolean cash=type.getSelectedItemPosition()==0;String tier=s(denomination);denomination.setEnabled(cash);
   if(compare){rateRow(rows,"Bank","Rate", "THB total",true);for(int i=0;i<BANKS.length;i++){JSONObject b=boards.get(i);String value="—",total="—";boolean buys=direction.getSelectedItemPosition()==0;
    if(b!=null){BigDecimal r=findRate(b,s(currency),cash,tier,buys);if(r!=null){value=r.stripTrailingZeros().toPlainString();try{BigDecimal n=new BigDecimal(amount.getText().toString());if(n.signum()>=0)total=n.multiply(r).setScale(2,RoundingMode.HALF_UP).toPlainString();}catch(Exception ignored){}}}
    rateRow(rows,BANKS[i],value,total,false);rows.addView(text(states.getOrDefault(i,"Awaiting data")+(b==null?"":" · "+b.optString("stamp")),11,MUTE,false));link(rows,"Bank website",BankRateService.URLS[i]);}
   }else{int i=chosen.getSelectedItemPosition();JSONObject b=boards.get(i);rateRow(rows,"Currency","BUY","SELL",true);if(b==null)rows.addView(text("No published rates available",15,ERROR,false));else{for(String cc:CURRENCIES){if(cc.equals("THB"))continue;BigDecimal buy=findRate(b,cc,cash,tier,true),sell=findRate(b,cc,cash,tier,false);if(buy!=null||sell!=null)rateRow(rows,cc,show(buy),show(sell),false);}}rows.addView(text(states.getOrDefault(i,"Awaiting data")+(b==null?"":" · Published "+b.optString("stamp")),12,MUTE,false));link(rows,"Official bank rate board",BankRateService.URLS[i]);}
  };
  Runnable fetch=()->{if(!active)return;final int g=generation,id=++request[0];boards.clear();states.clear();int first=compare?0:chosen.getSelectedItemPosition(),last=compare?BANKS.length-1:first;final int[] pending={last-first+1};status.setText("Checking bank websites…");for(int j=first;j<=last;j++){final int i=j;try{JSONObject b=new JSONObject(prefs.getString("board531:"+i,""));if(BANKS[i].equals(b.getString("bank"))){boards.put(i,b);states.put(i,"Cached");}}catch(Exception ignored){}BankRateService.fetch(i,(b,err)->{if(!active||g!=generation||id!=request[0])return;if(b!=null){JSONObject old=boards.get(i);if(old==null||b.optString("stamp").compareTo(old.optString("stamp"))>=0){boards.put(i,b);prefs.edit().putString("board531:"+i,b.toString()).apply();states.put(i,"Published board");}else states.put(i,"Cached · newer than response");}else states.put(i,(boards.containsKey(i)?"Cached":"Unavailable")+" · "+(err==null?"no data":err));render.run();if(--pending[0]==0)status.setText("Finished · check each publication time");});}render.run();};
  bankPoll=new Runnable(){public void run(){if(!active)return;fetch.run();timer.postDelayed(this,300000);}};resumeFetch=()->{timer.removeCallbacks(bankPoll);bankPoll.run();};selected(type,render);selected(denomination,render);if(compare){selected(currency,render);selected(direction,render);watch(amount,render);}else selected(chosen,fetch);
  action(l,"Refresh bank rates",fetch);l.addView(text("THB per 1 foreign unit · bank's side · fees excluded · indicative only. Compare identical note denominations and publication dates.",12,MUTE,false));if(compare)resumeFetch.run();else timer.postDelayed(bankPoll,300000);
 }
 static String show(BigDecimal x){return x==null?"—":x.stripTrailingZeros().toPlainString();}
 static BigDecimal findRate(JSONObject board,String cc,boolean cash,String tier,boolean buy){try{JSONArray rows=board.getJSONArray("rows");String k=(cash?"n":"t")+(buy?"b":"s");for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);if(!cc.equals(r.getString("ccy")))continue;if(cash&&cc.equals("USD")&&!tier.equals(r.optString("tier")))continue;if(r.has(k)){BigDecimal n=new BigDecimal(r.getString(k));if(n.signum()>0)return n;}}}catch(Exception ignored){}return null;}
 void rateRow(LinearLayout l,String a1,String a2,String a3,boolean header){LinearLayout r=row();r.setBackground(bg(header?FUNC:CARD));String[] v={a1,a2,a3};for(int i=0;i<3;i++){TextView t=text(v[i],header?12:14,i==0?WHITE:BLUE,header);t.setGravity(i==0?android.view.Gravity.START:android.view.Gravity.END);r.addView(t,new LinearLayout.LayoutParams(0,-2,i==0?1.5f:1));}LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(2),0,dp(2));l.addView(r,p);}
}
